SET LOCAL lock_timeout = '5s';
DO $p$
DECLARE
    me            oid := (SELECT r.oid FROM pg_catalog.pg_roles r WHERE r.rolname = current_user);
    pol_roles     oid[];
    exposed_roles text;
BEGIN
    IF to_regclass('nexus.aspect_extraction_queue') IS NOT NULL THEN
        DROP POLICY IF EXISTS aspect_extraction_queue_owner_read ON nexus.aspect_extraction_queue;
        CREATE POLICY aspect_extraction_queue_owner_read ON nexus.aspect_extraction_queue
            FOR SELECT TO CURRENT_USER USING (true);
        SELECT pol.polroles INTO pol_roles
          FROM pg_catalog.pg_policy pol
         WHERE pol.polrelid = 'nexus.aspect_extraction_queue'::regclass AND pol.polname = 'aspect_extraction_queue_owner_read';
        IF pol_roles IS DISTINCT FROM ARRAY[me] THEN
            RAISE EXCEPTION 'owner-read policy aspect_extraction_queue_owner_read must name exactly the migrating role % and nothing else, found %', current_user, pol_roles;
        END IF;
        SELECT string_agg(r.rolname, ', ' ORDER BY r.rolname) INTO exposed_roles
          FROM pg_catalog.pg_roles r
         WHERE (r.rolname = 'nexus_svc' AND (r.rolname = current_user OR pg_catalog.pg_has_role(r.oid, current_user, 'USAGE')))
            OR (r.rolname <> current_user AND pg_catalog.pg_has_role(r.oid, current_user, 'USAGE')
                AND NOT r.rolsuper AND NOT r.rolbypassrls AND r.rolcanlogin);
        IF exposed_roles IS NOT NULL THEN
            RAISE EXCEPTION 'role(s) % have the privileges of the migrating role %; the owner-read policy would apply to them and let them read every tenant''s rows of nexus.aspect_extraction_queue', exposed_roles, current_user;
        END IF;
    END IF;
END
$p$;

rollback.sql:
DO $r$
BEGIN
    IF to_regclass('nexus.aspect_extraction_queue') IS NOT NULL THEN
        DROP POLICY IF EXISTS aspect_extraction_queue_owner_read ON nexus.aspect_extraction_queue;
    END IF;
END
$r$;
